insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('bench','Dumbbell flat bench press','Chest',ARRAY['Dumbbells','Bench']::text[],'{"id":"bench","name":"Dumbbell flat bench press","primary":"Chest","secondary":["Triceps","Shoulders"],"gear":["Dumbbells","Bench"],"pose":"bench","steps":["Lie on a flat bench, feet planted and dumbbells beside your chest.","Keep wrists over elbows, elbows about 45° from your torso.","Press up over the chest; lower slowly to a comfortable depth."],"mistake":"Do not flare elbows or bounce the weights.","easy":"Dumbbell floor press","hard":"Pause briefly at the bottom","kind":"reps","load":"dumbbell","count":2,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('row','One-arm dumbbell row','Back',ARRAY['Dumbbells','Bench']::text[],'{"id":"row","name":"One-arm dumbbell row","primary":"Back","secondary":["Biceps"],"gear":["Dumbbells","Bench"],"pose":"row","steps":["Support one hand and knee on a stable bench; keep your spine neutral.","Let the working arm hang, then pull your elbow toward your hip.","Lower without twisting. Complete both sides."],"mistake":"Do not rotate the torso or shrug.","easy":"Lighter supported row","hard":"Three-second lowering","kind":"reps","load":"dumbbell","count":1,"unilateral":true,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('goblet','Goblet squat','Quadriceps',ARRAY['Dumbbells']::text[],'{"id":"goblet","name":"Goblet squat","primary":"Quadriceps","secondary":["Glutes","Abs"],"gear":["Dumbbells"],"pose":"squat","steps":["Hold one dumbbell vertically at your chest; feet about shoulder width.","Sit down between your hips, keeping heels grounded.","Stand by pushing through the whole foot."],"mistake":"Avoid knees collapsing inward.","easy":"Bodyweight squat to bench","hard":"Slow lowering and a pause","kind":"reps","load":"dumbbell","count":1,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('curl','Dumbbell bicep curl','Biceps',ARRAY['Dumbbells']::text[],'{"id":"curl","name":"Dumbbell bicep curl","primary":"Biceps","secondary":[],"gear":["Dumbbells"],"pose":"curl","steps":["Stand tall with palms forward and elbows beside your ribs.","Curl both weights without moving your upper arms.","Lower slowly until arms are comfortably extended."],"mistake":"Avoid swinging or leaning backward.","easy":"Use a lighter weight","hard":"Three-second lowering","kind":"reps","load":"dumbbell","count":2,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
