insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('incline','Incline dumbbell bench press','Chest',ARRAY['Dumbbells','Bench']::text[],'{"id":"incline","name":"Incline dumbbell bench press","primary":"Chest","secondary":["Shoulders","Triceps"],"gear":["Dumbbells","Bench"],"pose":"incline","steps":["Set the bench to a low incline (about 15–30° if available).","Plant your feet and hold weights beside your upper chest.","Press upward and lower under control."],"mistake":"Avoid excessive arching or a very steep angle.","easy":"Flat press or floor press","hard":"Pause at bottom","kind":"reps","load":"dumbbell","count":2,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('shoulder','Seated dumbbell shoulder press','Shoulders',ARRAY['Dumbbells','Bench']::text[],'{"id":"shoulder","name":"Seated dumbbell shoulder press","primary":"Shoulders","secondary":["Triceps"],"gear":["Dumbbells","Bench"],"pose":"press","steps":["Sit tall with feet grounded and dumbbells at shoulder height.","Press overhead within a comfortable range.","Lower slowly; keep ribs stacked over your pelvis."],"mistake":"Avoid arching your lower back.","easy":"Lighter weights with neutral grip","hard":"Slower lowering","kind":"reps","load":"dumbbell","count":2,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Use a comfortable, controlled range. Stop if you feel sharp pain or persistent discomfort."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
