insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('bands-curl','Resistance band curl','Biceps',ARRAY['Resistance bands']::text[],'{"id":"bands-curl","name":"Resistance band curl","primary":"Biceps","secondary":[],"gear":["Resistance bands"],"pose":"bandcurl","steps":["Inspect the band and stand securely on its middle with shoes on.","Hold handles with palms up and elbows beside you.","Curl slowly and return without releasing tension abruptly."],"mistake":"Do not stretch beyond the manufacturer limit.","easy":"Lower rated band","hard":"Slow return","kind":"reps","load":"band","count":1,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Inspect tubing and handles. Avoid damaged bands and uncomfortable pressure under your feet."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
