insert into public.exercises (id,name,primary_muscle,equipment,guide) values ('bands-row','Resistance band row','Back',ARRAY['Resistance bands']::text[],'{"id":"bands-row","name":"Resistance band row","primary":"Back","secondary":["Biceps"],"gear":["Resistance bands"],"pose":"bandrow","steps":["Use a manufacturer-approved secure anchor around torso height.","Stand tall with arms forward and tension in the band.","Draw elbows back, then return with control."],"mistake":"Do not lean back to move the resistance.","easy":"Lighter band","hard":"Pause with elbows back","kind":"reps","load":"band","count":1,"unilateral":false,"breath":"Exhale during the effort; inhale on the controlled return. Keep breathing.","safety":"Check the rated anchor before every set. Never attach to an unsecured door or furniture."}'::jsonb) on conflict (id) do update set name=excluded.name,primary_muscle=excluded.primary_muscle,equipment=excluded.equipment,guide=excluded.guide;
